@Test
public void testIndexMustHaveValue() throws IOException, InterruptedException {
    String input = "123";
    when(rr.getCurrentValue()).thenReturn(new Text(input));
    TextVertexReader vr = createVertexReader(rr);
    vr.setConf(conf);
    vr.initialize(null, tac);
    try {
        vr.nextVertex();
        vr.getCurrentVertex();
